def _e_BinOp(self, node: ast.BinOp) -> str:
    left = self._gen_expr(node.left)
    right = self._gen_expr(node.right)
    lt = self._infer(node.left)
    rt = self._infer(node.right)
    is_float = isinstance(lt, FloatType) or isinstance(rt, FloatType)
    if isinstance(node.op, ast.Add) and (
        isinstance(lt, StrType) or isinstance(rt, StrType)
    ):
        return f"py_strcat({left}, {right})"
    if isinstance(node.op, ast.Pow):
        if is_float:
            return f"pow({left}, {right})"
        return f"py_ipow({left}, {right})"
    if isinstance(node.op, ast.FloorDiv):
        if is_float:
            return f"py_ffloordiv((double)({left}), (double)({right}))"
        return f"py_floordiv({left}, {right})"
    if isinstance(node.op, ast.Div):
        # Python '/' is always true division -> force double.
        return f"py_fdiv((double)({left}), (double)({right}))"
    if isinstance(node.op, ast.Mod):
        if is_float:
            return f"py_fmod((double)({left}), (double)({right}))"
        if isinstance(lt, StrType):
            raise UnsupportedError(
                "str %-formatting not supported by C backend", node)
        return f"py_mod({left}, {right})"
    sym = self._binop_sym(node.op)
    return f"({left} {sym} {right})"
